// The asset fixtures of task M4-06 (decision 0060): `fixtures/m4/assets_scene` and `fixtures/m4/assets_corrupt`, generated by
// `tests/assets/tools/make-glb.mjs` and built by global setup like every M4 fixture (`mtek build --mode test` into
// `.out/m4/<name>/`, served as `<server>/m4/<name>/index.html`). These helpers read the sources and the built manifest so the
// spec can state where each declaration is without hard-coding line numbers.
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { M4_FIXTURES_DIR, M4_OUT_DIR } from "./m4-fixtures.ts";

export const ASSET_SCENE = "assets_scene";
export const ASSET_CORRUPT = "assets_corrupt";

export interface ManifestAsset {
  readonly url: string;
  readonly sha256: string;
  readonly bytes: number;
  readonly kind: "mesh-data" | "image" | "audio";
  readonly colorSpace?: "srgb" | "linear";
  readonly span: number;
}

export interface BuiltManifest {
  readonly assets: readonly ManifestAsset[];
  readonly spans: ReadonlyArray<{ readonly startLine: number; readonly startColumn: number }>;
}

export function fixtureFile(name: string, path: string): Buffer {
  return readFileSync(join(M4_FIXTURES_DIR, name, path));
}

export function fixtureSource(name: string): string {
  return readFileSync(join(M4_FIXTURES_DIR, name, "src", "main.mtek"), "utf8");
}

export function builtManifest(name: string): BuiltManifest {
  return JSON.parse(readFileSync(join(M4_OUT_DIR, name, "program.manifest.json"), "utf8")) as BuiltManifest;
}

/** The `file:line:column` the overlay shows for the first occurrence of `literal` in the fixture's `src/main.mtek` (1-based). */
export function locationOf(name: string, literal: string): string {
  const source = fixtureSource(name);
  const offset = source.indexOf(literal);
  if (offset < 0) throw new Error(`${literal} does not occur in fixtures/m4/${name}/src/main.mtek`);
  const before = source.slice(0, offset).split("\n");
  return `src/main.mtek:${String(before.length)}:${String((before.at(-1)?.length ?? 0) + 1)}`;
}

/** The manifest entry for the packaged copy of a fixture file: images are copied byte for byte, so the digests agree. */
export function assetOfFile(name: string, path: string): ManifestAsset {
  const sha = createHash("sha256").update(fixtureFile(name, path)).digest("hex");
  const found = builtManifest(name).assets.find((asset) => asset.sha256 === sha);
  if (found === undefined) throw new Error(`no asset of ${name} has the digest of ${path}`);
  return found;
}

/** The manifest's `mesh-data` entry (the fixture has one GLB). */
export function meshDataAsset(name: string): ManifestAsset {
  const found = builtManifest(name).assets.find((asset) => asset.kind === "mesh-data");
  if (found === undefined) throw new Error(`${name} has no mesh-data asset`);
  return found;
}

/** The path of a built asset file inside `.out/`. */
export function builtAssetPath(name: string, asset: ManifestAsset): string {
  return join(M4_OUT_DIR, name, asset.url);
}
